extends SceneTree

func _init():
	var instance_field = preload("res://instancing/instance_field.gd").new()
	var mm = instance_field.build()

	var dir = DirAccess.open("res://")
	if not dir.dir_exists("build"):
		dir.make_dir("build")

	var err = ResourceSaver.save(mm, "res://build/field.res")
	if err != OK:
		push_error("Failed to save field.res: %d" % err)
		quit(1)

	var box_min = Vector3(-1.0, 0.0, -3.0)
	var box_max = Vector3(5.0, 1.5, 0.0)

	var result = instance_field.cull(box_min, box_max)

	var report = {
		"instance_count": 120,
		"transform_format": 1,
		"use_colors": true,
		"use_custom_data": true,
		"query_min": [box_min.x, box_min.y, box_min.z],
		"query_max": [box_max.x, box_max.y, box_max.z],
		"visible_indices": result.indices,
		"visible_count": result.count,
		"weight_sum": result.weight_sum,
		"flagged_count": result.flagged_count
	}

	var file = FileAccess.open("res://build/report.json", FileAccess.WRITE)
	if not file:
		push_error("Failed to open report.json for writing")
		quit(1)
	file.store_string(JSON.stringify(report, "	"))
	file.close()

	print("Done.")
	quit(0)

