func _init():
	var mm = MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.use_colors = true
	mm.use_custom_data = true
	mm.instance_count = 120

	var b = PackedFloat32Array()
	b.resize(120 * 20)
	b[0] = 1.23
	mm.buffer = b

	var err = ResourceSaver.save(mm, "res://test.res")
	if err != OK: print("save fail: ", err); quit(1)

	var mm2 = ResourceLoader.load("res://test.res")
	if not mm2: print("load fail"); quit(1)

	print("mm2 buffer size: ", mm2.buffer.size())
	if mm2.buffer.size() > 0:
		print("mm2 buffer[0]: ", mm2.buffer[0])
	else:
		print("mm2 buffer is empty")
	quit()
